export const setCssStyle = function (id: string, styles: string[]) {
  const thisClass = classes[id];
  if (!styles || !thisClass) {
    return;
  }
  for (const s of styles) {
    if (s.includes(',')) {
      thisClass.styles = thisClass.styles.concat(s.split(','));
    } else {
      thisClass.styles.push(s);
    }
  }
};
